walk!(base,base_base);walk!(generic,candidate_base);walk!(prefix,base_candidate);walk!(both,candidate_candidate);walk!(guard,guarded);walk!(scan,scanned);
fn main(){
 let mut seed=1122u32;let mut cases=Vec::new();
 for i in 0..96{let n=[15,49,51][i%3];let mut c=Case{coded:[false;51],bits:[[u32::MAX;12];51],n,short:i%3==0};
