   for cb in 1..12{seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);c.bits[b][cb]=if i%4==0{40+cb as u32}else if seed%7==0&&cb!=11{u32::MAX}else{1+seed%80};}
