/// no-go as default: < 2% section+spectral savings).
pub(super) fn plan_books_into(
    coded: &[bool],
    bits: &[[u32; BOOKS]],
    n: usize,
    sfb_cb: &mut [u8],
    header_bits: fn(usize) -> usize,
) {
    let costs = cost::CostPrefix::new(coded, bits, n);
    for b in 0..n {
        sfb_cb[b] = if coded[b] {
            best_single_book(&bits[b])
        } else {
            0
        };
    }
    let mut improved = true;
    while improved {
        improved = false;
        let mut lo = 0usize;
        while lo < n {
            if !coded[lo] {
                lo += 1;
                continue;
            }
            let mut hi = lo + 1;
            while hi < n && coded[hi] {
                hi += 1;
            }
            let mut i = lo;
            while i < hi {
                let mut j = i + 1;
                while j < hi && sfb_cb[j] == sfb_cb[i] {
                    j += 1;
                }
                if j < hi {
                    let mut k = j + 1;
                    while k < hi && sfb_cb[k] == sfb_cb[j] {
                        k += 1;
                    }
                    let saved = header_bits(j - i) as i64 + header_bits(k - j) as i64
                        - header_bits(k - i) as i64;
                    if let Some((cb, merged)) = costs.best(i, k) {
                        let cur = costs
                            .range(i, j, usize::from(sfb_cb[i]))
                            .saturating_add(costs.range(j, k, usize::from(sfb_cb[j])));
                        if i64::from(merged) - i64::from(cur) < saved {
                            sfb_cb[i..k].fill(cb);
                            improved = true;
                        }
                    }
                }
                i = j;
            }
            lo = hi;
        }
    }
    #[cfg(debug_assertions)]
    {
        let mut alt = [0u8; MAX_BANDS];
        exact::plan_books_dp(coded, bits, n, &mut alt, header_bits);
        debug_assert!(
            exact::section_spectral_cost(sfb_cb, coded, bits, n, header_bits)
                >= exact::section_spectral_cost(&alt, coded, bits, n, header_bits)
        );
    }
}

